import{_ as o,o as a,c as t,ae as s}from"./chunks/framework.Dn6zxbF8.js";const m=JSON.parse('{"title":"Acronyms Usage","description":"","frontmatter":{"id":"6819030042","title":"Acronyms Usage","state":"Approved","created":"2024-09-27T00:00:00.000Z","tags":["naming","acronyms"],"category":"Platform"},"headers":[],"relativePath":"adrs/6819030042/README.md","filePath":"adrs/6819030042/README.md"}'),n={name:"adrs/6819030042/README.md"};function i(r,e,c,l,d,u){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="acronyms-usage" tabindex="-1">Acronyms Usage <a class="header-anchor" href="#acronyms-usage" aria-label="Permalink to &quot;Acronyms Usage&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Inconsistency in the usage of acronyms within codebases leads to debates over naming conventions, making code reviews and collaboration more challenging—especially for non-native English speakers. Promoting unnecessary discussions and detracts from more critical development tasks.</p><p>A simple internet search reveals numerous conflicting opinions on how to handle acronyms in naming conventions. For example, consider XMLHttpRequest from browser APIs.</p><ul><li>Which naming convention provides the best readability and consistency?</li><li>How should acronyms be integrated into different casing styles like camelCase, PascalCase, or snake_case?</li><li>How should acronyms be handled in programming languages with strict naming conventions, such as Go?</li></ul><p>In Go, for instance, <code>type HTTPHeader</code> and <code>type httpHeader</code> are not the same, which can lead to errors. This is because Go uses the visibility of the first letter to determine whether a variable or function is public or private. This means that <code>HTTPHeader</code> is public, while <code>httpHeader</code> is private.</p><p>Should it be <code>type hTTP</code>?</p><p>Familiar acronyms will be understood regardless of their form. Until we encounter quantifiable and quantifiable evidence that one form is more readable than another, we are moving forward with the following guidelines.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li>You <strong>MUST NOT</strong> use upper case acronyms in names in source code across all languages, regardless of their preferred casing style. <ul><li>Except for technical limitations</li><li>Except for declaring constants in all caps, where the acronym is part of the name.</li></ul></li><li>You <strong>MAY</strong> use proper acronyms spelling in documentation.</li><li>You <strong>MAY</strong> spell out the acronym provided they are defined upon first use within the documentation.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><ul><li>Instead of <code>XMLHttpRequest</code>, use <code>XmlHttpRequest</code>.</li><li>Instead of <code>HTTPServer</code>, use <code>HttpServer</code>.</li><li>Instead of <code>URL</code>, use <code>Url</code>.</li><li>Instead of <code>ID</code>, use <code>Id</code>.</li><li>Instead of <code>API</code>, use <code>Api</code>.</li><li>Instead of <code>TCP</code>, use <code>Tcp</code>.</li><li>Instead of <code>HTTP</code>, use <code>Http</code>.</li><li>Instead of <code>JSON</code>, use <code>Json</code>.</li><li>Instead of <code>HTML</code>, use <code>Html</code>.</li><li>Instead of <code>CSS</code>, use <code>Css</code>.</li><li>Instead of <code>CLI</code>, use <code>Cli</code>.</li></ul>',12)])])}const p=o(n,[["render",i]]);export{m as __pageData,p as default};
